    public static String getContentFromURL(String urlString) throws MalformedURLException {
        // Validasi URL
        URL url = new URL(urlString);

        // Membersihkan host dari karakter tidak valid
        String host = url.getHost().replaceAll("\\s", "");

        // Membuat URL baru dengan host yang sudah dikosongi
        URL validUrl = new URL(url.getProtocol(), host, url.getPort(), url.getFile());

        // Mengambil konten dari URL yang valid
        return getContent(validUrl);
    }

    /**
     * Mengambil konten dari URL yang diberikan.
     * 
     * @param url URL yang akan diambil kontennya
     * @return Konten dari URL
     * @throws Exception Jika terjadi kesalahan saat mengambil konten
     */
    private static String getContent(URL url) throws Exception {
        // Implementasi untuk mengambil konten dari URL
        // Misalnya, menggunakan HttpURLConnection atau HttpClient
        // Ini adalah contoh sederhana menggunakan HttpURLConnection
        try (java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(url.openStream()))) {
            StringBuilder content = new StringBuilder();
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            return content.toString();
        }
    }
}
