            // 创建 URL 对象
            URL url = new URL(urlString);

            // 清理主机名，移除空格等无效字符
            String host = url.getHost().replaceAll("\\s+", "");

            // 重新构建 URL
            URL cleanedUrl = new URL(url.getProtocol(), host, url.getPort(), url.getFile());

            // 打开连接并获取内容
            return new java.io.BufferedReader(new java.io.InputStreamReader(cleanedUrl.openStream())).readLine();
        } catch (URISyntaxException | java.io.IOException e) {
            e.printStackTrace();
            return null;
        }
    }
}
