     * 
     * @param urlString URL yang ingin diambil kandungannya
     * @return Kandungan URL jika sukses, null jika gagal
     */
    public static String fetchURLContent(String urlString) {
        try {
            // Membuat URL objek
            URL url = new URL(urlString);

            // Membuka koneksi ke URL
            BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()));

            // Membaca dan menyimpan kandungan URL
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) {
                content.append(line);
            }
            in.close();

            // Membersihkan hos dengan menghapus karakter tidak sah seperti ruang
            String cleanedHost = url.getHost().replaceAll("\\s", "");

            return "Kandungan URL: " + content.toString() + "\nHos: " + cleanedHost;
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }

    public static void main(String[] args) {
        String urlString = "http://example.com";
        String result = fetchURLContent(urlString);
        if (result != null) {
            System.out.println(result);
        } else {
            System.out.println("Gagal mengambil kandungan URL.");
        }
    }
}
