import java.net.URL;
import java.net.MalformedURLException;

public class ClassX {
    /**
     * Haal inhoud op van een gegenereerde URL na het valideren van de host.
     * 
     * Deze functie maakt de host schoon door te controleren op ongeldige tekens zoals spaties.
     */
    public static String fetchContent(String urlString) {
        try {
            // Maak een URL-object van de URL-string
            URL url = new URL(urlString);

            // Haal de host van de URL
            String host = url.getHost();

            // Controleer of de host geen ongeldige tekens bevat
            if (host.contains(" ")) {
                throw new IllegalArgumentException("Host contains invalid characters.");
            }

            // Haal de inhoud van de URL
            return url.openStream().toString();
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid URL format.", e);
        } catch (IllegalArgumentException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("An error occurred while fetching content.", e);
        }
    }
}
```

