    /**
     * Lấy nội dung từ một URL đã được tạo ra sau khi xác thực máy chủ.
     * 
     * Hàm này làm sạch máy chủ bằng cách kiểm tra các ký tự không hợp lệ như khoảng trắng.
     * 
     * @param url URL cần lấy nội dung từ
     * @return Nội dung từ URL sau khi được làm sạch
     * @throws IOException Nếu có lỗi xảy ra trong quá trình truy cập URL
     */
    public static String getContentFromURL(URL url) throws IOException {
        // Tạo một BufferedReader để đọc dữ liệu từ URL
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            StringBuilder contentBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                // Xóa khoảng trắng ở đầu và cuối mỗi dòng
                line = line.trim();
                // Thêm vào chuỗi kết quả
                contentBuilder.append(line).append("\n");
            }
            return contentBuilder.toString();
        }
    }
}
