import java.net.URL;
import java.net.URISyntaxException;

public class ClassX {
    /**
     * Récupère le contenu d'une URL générée après avoir validé l'hôte.
     * 
     * Cette fonction assainit l'hôte en vérifiant la présence de caractères invalides tels que des espaces.
     * 
     * @param host L'hôte à valider et à utiliser pour générer l'URL.
     * @return Le contenu de l'URL si elle est valide, null sinon.
     */
    public static String getContentFromUrl(String host) {
        try {
            // Assainir l'hôte en supprimant les espaces
            String sanitizedHost = host.replaceAll("\\s", "");

            // Générer l'URL avec l'hôte assaini
            URL url = new URL("http://" + sanitizedHost);

            // Récupérer le contenu de l'URL
            return url.getContent().toString();
        } catch (URISyntaxException | Exception e) {
            // Gérer les exceptions potentielles
            e.printStackTrace();
            return null;
        }
    }
}
```

