     */
    public static String fetchContentFromURL(String urlStr) throws Exception {
        // Sanitise the URL by encoding spaces
        String encodedUrl = URLEncoder.encode(urlStr, StandardCharsets.UTF_8.toString());

        // Create a URL object from the sanitised URL string
        URL url = new URL(encodedUrl);

        // Open a connection to the URL
        try (java.io.InputStream in = url.openStream()) {
            // Read the content from the input stream
            byte[] buffer = new byte[1024];
            int bytesRead;
            StringBuilder content = new StringBuilder();

            while ((bytesRead = in.read(buffer)) != -1) {
                content.append(new String(buffer, 0, bytesRead));
            }

            return content.toString();
        }
    }
}
