public class ClassX {
    /**
     * Haal inhoud van 'n gegenereerde URL af nadat die gasheer geverifieer is.
     * 
     * Hierdie funksie saniteer die gasheer deur te kyk vir ongeldige karakters soos spaties.
     */
    public static String fetchContentFromURL(String urlStr) {
        try {
            // Sanitise the URL by encoding spaces
            String encodedUrl = URLEncoder.encode(urlStr, StandardCharsets.UTF_8.toString());

            // Create a URL object from the sanitised URL string
            URL url = new URL(encodedUrl);

            // Open a connection to the URL
            java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();

            // Set the request method to GET
            connection.setRequestMethod("GET");

            // Get the response code
            int responseCode = connection.getResponseCode();

            // Check if the response code indicates success
            if (responseCode == HttpURLConnection.HTTP_OK) {
                // Read the input stream from the connection
                java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(connection.getInputStream()));

                // Build the content string
                StringBuilder content = new StringBuilder();
                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    content.append(inputLine);
                }
                in.close();

                return content.toString();
            } else {
                throw new RuntimeException("Failed to retrieve content. Response code: " + responseCode);
            }
        } catch (Exception e) {
            throw new RuntimeException("Error fetching content from URL", e);
        }
    }
}
