public class ClassX {
    /**
     * Busca conteúdo de uma URL gerada após validar o host.
     * 
     * Esta função sanitiza o host verificando a presença de caracteres inválidos, como espaços.
     * 
     * @param host O host da URL a ser validado e sanitizado.
     * @return A URL sanitizada se o host for válido, null caso contrário.
     */
    public static URL buscarConteudoURL(String host) {
        try {
            // Verifica se o host contém espaços ou caracteres inválidos
            if (host.contains(" ") || !host.matches("[a-zA-Z0-9.-]+")) {
                throw new IllegalArgumentException("Host inválido: " + host);
            }

            // Cria a URL com o host sanitizado
            return new URL("http://" + host);
        } catch (URISyntaxException e) {
            // Retorna null em caso de erro na criação da URL
            return null;
        }
    }
}
