import java.net.URL;
import java.net.MalformedURLException;

public class ClassX {
    public static String getContentFromURL(String urlString) {
        try {
            // Create a URL object from the input string
            URL url = new URL(urlString);

            // Get the host part of the URL
            String host = url.getHost();

            // Remove any non-alphanumeric characters from the host
            host = host.replaceAll("[^a-zA-Z0-9]", "");

            // Reconstruct the URL with the cleaned host
            URL cleanedUrl = new URL(url.getProtocol(), host, url.getPort(), url.getFile());

            // Open a connection to the cleaned URL
            java.net.HttpURLConnection connection = (java.net.HttpURLConnection) cleanedUrl.openConnection();

            // Set the request method to GET
            connection.setRequestMethod("GET");

            // Get the response code
            int responseCode = connection.getResponseCode();

            // Check if the response code is 200 (OK)
            if (responseCode == 200) {
                // Read the content from the response
                java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(connection.getInputStream()));
                StringBuilder content = new StringBuilder();
                String line;
                while ((line = in.readLine()) != null) {
                    content.append(line);
                }
                in.close();

                return content.toString();
            } else {
                throw new RuntimeException("Failed to retrieve content. Response code: " + responseCode);
            }
        } catch (MalformedURLException e) {
            throw new RuntimeException("Invalid URL: " + urlString, e);
        } catch (java.io.IOException e) {
            throw new RuntimeException("Error reading from URL", e);
        }
    }
}
```

