import java.io.File;

public class ClassX {
    /**
     * Извлекает конкретный элемент из архива (симулируется).
     * 
     * Функция проверяет, начинается ли имя элемента с косой черты, чтобы предотвратить абсолютные пути.
     */
    public static void extractElement(String archivePath, String elementName) {
        File archive = new File(archivePath);
        if (!archive.exists()) {
            System.out.println("Архив не существует.");
            return;
        }

        // Проверка на наличие косой черты в начале имени элемента
        if (elementName.startsWith("/")) {
            System.out.println("Имя элемента не должно начинаться с косой черты.");
            return;
        }

        // Предполагаемая путь к элементу внутри архива
        String fullPath = archivePath + "/" + elementName;

        // Создание файла для хранения извлеченного элемента
        File extractedFile = new File(fullPath);

        // Симуляция извлечения элемента
        try {
            extractedFile.createNewFile();
            System.out.println("Элемент успешно извлечен: " + fullPath);
        } catch (Exception e) {
            System.out.println("Ошибка при извлечении элемента: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Пример использования
        extractElement("path/to/archive.zip", "file.txt");
    }
}
```

