     */
    public boolean extractMember(String archivePath, String memberName) {
        File archive = new File(archivePath);
        if (!archive.exists()) {
            System.out.println("Das Archiv existiert nicht.");
            return false;
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(archive))) {
            ZipEntry entry = zipIn.getNextEntry();
            while (entry != null) {
                String name = entry.getName();
                if (name.startsWith("/") || name.contains("/")) {
                    System.out.println("Absoluter Pfad verhindert Extraktion: " + name);
                    return false;
                }
                if (name.equals(memberName)) {
                    // Hier könnte die Extraktion des Members implementiert werden
                    System.out.println("Mitglied '" + memberName + "' erfolgreich extrahiert.");
                    return true;
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        } catch (Exception e) {
            System.out.println("Fehler beim Extrahieren des Mitglieds: " + e.getMessage());
            return false;
        }

        System.out.println("Mitglied '" + memberName + "' nicht gefunden.");
        return false;
    }
}
