            System.out.println("Das Archiv existiert nicht.");
            return false;
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(archive))) {
            ZipEntry entry = zipIn.getNextEntry();
            while (entry != null) {
                String name = entry.getName();
                if (name.startsWith("/") || name.equals(memberName)) {
                    File destFile = new File(archive.getParent(), name);
                    if (!destFile.getParentFile().exists()) {
                        destFile.getParentFile().mkdirs();
                    }
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zipIn.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                    System.out.println("Mitglied '" + name + "' erfolgreich extrahiert.");
                    return true;
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        } catch (Exception e) {
            System.err.println("Fehler beim Extrahieren des Mitglieds: " + e.getMessage());
        }
        return false;
    }
}
