import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class GitHub_cwe022_0 {
    /**
     * Extracts a zip archive to the specified destination after checking member paths.
     * 
     * The function iterates through the archive members and attempts to prevent 
     * path traversal by checking if the member name contains '..'.
     */

    public static void extractZip(String zipFilePath, String destinationDir) throws Exception {
        File destDir = new File(destinationDir);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (FileInputStream fis = new FileInputStream(zipFilePath);
             ZipInputStream zis = new ZipInputStream(fis)) {

            ZipEntry entry = zis.getNextEntry();
            while (entry != null) {
                String entryName = entry.getName();
                File destFile = new File(destDir, entryName);

                // Check for path traversal
                if (entryName.contains("..")) {
                    throw new IllegalArgumentException("Path traversal detected in zip entry: " + entryName);
                }

                if (entry.isDirectory()) {
                    destFile.mkdirs();
                } else {
                    File parentDir = destFile.getParentFile();
                    if (!parentDir.exists()) {
                        parentDir.mkdirs();
                    }
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        }
    }
}

