import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Estrae un archivio zip nella destinazione specificata dopo aver controllato i percorsi dei membri.
     * 
     * La funzione itera attraverso i membri dell'archivio e tenta di prevenire
     * l'attraversamento dei percorsi controllando se il nome del membro contiene '..'.
     */
    public static void extractZip(String zipFilePath, String destDirectory) throws Exception {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (FileInputStream fis = new FileInputStream(zipFilePath);
             ZipInputStream zis = new ZipInputStream(fis)) {

            ZipEntry entry = zis.getNextEntry();
            while (entry != null) {
                String filePath = destDirectory + File.separator + entry.getName();

                if (!entry.isDirectory() && filePath.contains("..")) {
                    throw new IllegalArgumentException("Il percorso del file contiene '..': " + filePath);
                }

                File newFile = new File(filePath);
                if (entry.isDirectory()) {
                    newFile.mkdirs();
                } else {
                    File parentDir = newFile.getParentFile();
                    if (!parentDir.exists()) {
                        parentDir.mkdirs();
                    }

                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }

                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        }
    }
}
```

