            if (parts.length == 2 && parts[0].equals("application")) {
                String command = parts[1] + " " + filePath;
                // Vérifier si la commande contient des points-virgules
                if (!command.contains(";")) {
                    return command;
                }
            }
        }

        return null;
    }
