import java.io.InputStreamReader;

public class ClassX {
    public static void main(String[] args) {
        String mimeType = "text/plain"; // Ejemplo de mime_type
        String command = buildCommand(mimeType);
        if (command != null) {
            executeCommand(command);
        } else {
            System.out.println("No se encontró un comando para el mime_type: " + mimeType);
        }
    }

    private static String buildCommand(String mimeType) {
        // Implementación de la lógica para construir el comando
        // Verificar si el mime_type es válido y construir el comando correspondiente
        // Evitar concatenación de comandos bloqueando los puntos y comas
        return "open " + mimeType; // Ejemplo de construcción
    }

    private static void executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            int exitCode = process.waitFor();
            System.out.println("Comando finalizado con código de salida: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
