import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Renders a template including user input.
     * 
     * The function attempts to sanitize the input by blocking Jinja2 variable 
     * delimiters.
     * 
     * @param template The template string containing Jinja2 variables.
     * @param userInput The user input to be included in the template.
     * @return The rendered template with sanitized user input.
     */
    public String renderTemplate(String template, String userInput) {
        // Define a regular expression pattern to match Jinja2 variable delimiters
        Pattern jinjaPattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Create a matcher for the input string
        Matcher matcher = jinjaPattern.matcher(userInput);

        // Replace Jinja2 variable delimiters with a placeholder
        String sanitizedInput = matcher.replaceAll("{{placeholder}}");

        // Replace the placeholder in the template with the sanitized input
        return template.replace("{{placeholder}}", sanitizedInput);
    }
}
