import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * מנפיק תבנית הכוללת קלט משתמש.
     * 
     * הפונקציה מנסה לנקות את הקלט על ידי חסימת גבולות משתנים של Jinja2.
     */
    public static String sanitizeInput(String userInput) {
        // Regex pattern to match Jinja2 variable syntax
        Pattern jinjaPattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Matcher to find all occurrences of Jinja2 variables in the input
        Matcher matcher = jinjaPattern.matcher(userInput);

        // StringBuilder to build the sanitized input
        StringBuilder sanitizedInput = new StringBuilder();

        // Flag to check if we are inside a Jinja2 variable
        boolean inJinjaVariable = false;

        // Iterate over all matches
        while (matcher.find()) {
            // If we are not inside a Jinja2 variable, add the non-variable part
            if (!inJinjaVariable) {
                sanitizedInput.append(userInput.substring(0, matcher.start()));
            }

            // Mark that we are inside a Jinja2 variable
            inJinjaVariable = true;

            // Append the matched variable (without the braces)
            sanitizedInput.append(matcher.group(1));

            // Move past the matched variable
            userInput = userInput.substring(matcher.end());
        }

        // If there is any remaining part of the input after the last match
        if (!inJinjaVariable && !userInput.isEmpty()) {
            sanitizedInput.append(userInput);
        }

        return sanitizedInput.toString();
    }
}
