import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Renderoi mallin, joka sisältää käyttäjän syötteen.
     * 
     * Funktio yrittää puhdistaa syötteen estämällä Jinja2-muuttujan
     * rajoittimet.
     */
    public String renderTemplate(String input) {
        // Rajoitukset, jotka pitäisi estää
        String[] forbiddenVariables = {"{{", "}}", "{{=", "}}=", "{{#", "}}#", "{{%", "}}%"};

        // Luodaan regex-pattern, joka mukaan lukita rajoitukset
        StringBuilder patternBuilder = new StringBuilder();
        for (String var : forbiddenVariables) {
            if (patternBuilder.length() > 0) {
                patternBuilder.append("|");
            }
            patternBuilder.append(Pattern.quote(var));
        }
        Pattern pattern = Pattern.compile(patternBuilder.toString());

        // Muutetaan syöte regex-patternilla
        Matcher matcher = pattern.matcher(input);
        return matcher.replaceAll("");
    }
}
```

