import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pingt einen angegebenen Host.
     * 
     * Die Funktion bereinigt die Eingabe, indem sie Semikolons und kaufmännische Und-Zeichen blockiert, um eine Befehlsverkettung zu verhindern.
     */
    public static void pingHost(String host) {
        // Bereinige die Eingabe
        String cleanedHost = host.replaceAll("[;&&]", "");

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec("ping " + cleanedHost).getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (Exception e) {
            System.err.println("Fehler beim Pingen des Hosts: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Bitte geben Sie einen Hostnamen ein.");
            return;
        }

        String host = args[0];
        pingHost(host);
    }
}
```

