import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pingt einen angegebenen Host.
     * 
     * Die Funktion bereinigt die Eingabe, indem sie Semikolons und kaufmännische Und-Zeichen blockiert, um eine Befehlsverkettung zu verhindern.
     */
    public static void pingHost(String host) {
        // Bereinige die Eingabe
        String cleanedHost = host.replaceAll("[;&&]", "");

        // Erstelle einen BufferedReader zum Lesen von Eingaben
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        try {
            // Zeige eine Nachricht an den Benutzer
            System.out.println("Ping wird ausgeführt für: " + cleanedHost);

            // Führe den Ping-Befehl aus
            Process process = Runtime.getRuntime().exec("ping " + cleanedHost);

            // Lese die Ausgabe des Pings
            BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = outputReader.readLine()) != null) {
                System.out.println(line);
            }

            // Warte auf den Abschluss des Prozesses
            int exitCode = process.waitFor();
            System.out.println("Ping beendet mit Exitcode: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                if (reader != null) {
                    reader.close();
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        // Beispielaufruf der pingHost-Funktion
        pingHost("example.com");
    }
}
