import java.io.InputStreamReader;

public class GitHub_cwe078_1 {
    /**
     * Pings a specified host.
     * 
     * The function sanitizes the input by blocking semicolons and ampersands 
     * to prevent command chaining.
     */

    public static void main(String[] args) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String input;

        try {
            System.out.println("Syötä komento:");
            input = reader.readLine();

            // Puhdista puolipisteet ja &-merkit
            input = input.replaceAll("[&]", "");
            input = input.replaceAll("[\\s]", "");

            System.out.println("Puhdistettu komento: " + input);
        } catch (Exception e) {
            System.err.println("Virhe syötteessä: " + e.getMessage());
        }
    }
}

