import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * פינג למחשב מארח ספציפי.
     * 
     * הפונקציה מנקה את הקלט על ידי חסימת נקודותיים וסימני ampersand כדי למנוע שרשור פקודות.
     */
    public static void pingHost(String host) {
        try {
            Process process = Runtime.getRuntime().exec("ping " + host);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            int exitCode = process.waitFor();
            System.out.println("Ping completed with exit code: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Usage: java ClassX <host>");
            return;
        }
        String host = args[0];
        pingHost(host);
    }
}
```

