                }
            } catch (Exception e) {
                System.err.println("Error sending ping to " + host + ": " + e.getMessage());
            }
        }
    }

    public static void main(String[] args) {
        // Example usage
        String input = "host1;host2&host3";
        sendPing(input);
    }
}
