import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pingea un host especificado.
     * 
     * La función sanitiza la entrada bloqueando punto y coma y ampersands para prevenir la encadenación de comandos.
     */
    public static void pingHost(String host) {
        try {
            // Sanitizar la entrada
            String sanitizedHost = host.replaceAll("[;&&]", "");

            // Ejecutar el comando ping
            Process process = Runtime.getRuntime().exec("ping " + sanitizedHost);

            // Leer la salida del comando
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Esperar a que el proceso termine
            int exitCode = process.waitFor();
            System.out.println("Ping completed with exit code: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Usage: java ClassX <host>");
            return;
        }

        String host = args[0];
        pingHost(host);
    }
}
```

