import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pinge un hôte spécifié.
     * 
     * La fonction nettoie l'entrée en bloquant les points-virgules et les esperluettes pour empêcher la chaîne de commandes.
     */
    public static void pingHost(String host) {
        try {
            // Nettoyage de l'entrée pour éviter les problèmes avec les commandes
            String cleanedHost = host.replaceAll(";", "").replaceAll("\"", "");

            // Construction de la commande ping
            String command = "ping -c 4 " + cleanedHost;

            // Exécution de la commande
            Process process = Runtime.getRuntime().exec(command);

            // Lecture de la sortie standard
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Lecture de l'erreur standard (si nécessaire)
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
            }

            // Attente de la fin du processus
            int exitCode = process.waitFor();
            System.out.println("Process exited with code: " + exitCode);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Usage: java ClassX <host>");
            return;
        }

        String host = args[0];
        pingHost(host);
    }
}
```

