    /**
     * Pinga un host specificato.
     * 
     * La funzione sanifica l'input bloccando i punti e virgola e le e commerciali per prevenire la concatenazione dei comandi.
     */
    public static void pingHost(String host) {
        try {
            // Sanifico l'input
            String sanitizedHost = host.replaceAll("[.;\\$]", "");

            // Creo un processo per eseguire il comando ping
            ProcessBuilder pb = new ProcessBuilder("ping", sanitizedHost);
            Process process = pb.start();

            // Leggo l'output del comando
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Aspetto che il processo termini
            int exitCode = process.waitFor();
            System.out.println("Ping terminato con codice di uscita: " + exitCode);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Usage: java ClassX <host>");
            return;
        }

        String host = args[0];
        pingHost(host);
    }
}
