public class ClassX {
    /**
     * Belirtilen bir ana bilgisayara ping atar.
     * 
     * Fonksiyon, komut zincirlemesini önlemek için girişte noktalı virgülleri ve ampersandları engelleyerek veriyi temizler.
     */
    public static void main(String[] args) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.println("Ping edilecek ana bilgisayar adını veya IP adresini girin:");
        String input = null;
        try {
            input = reader.readLine();
        } catch (Exception e) {
            System.out.println("Hata: " + e.getMessage());
        }

        if (input != null) {
            // Temizleme işlemi
            input = input.replaceAll("[.,&]", "");

            // Ping komutunu çalıştır
            try {
                Process process = Runtime.getRuntime().exec("ping " + input);
                BufferedReader in = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = in.readLine()) != null) {
                    System.out.println(line);
                }
                in.close();
            } catch (Exception e) {
                System.out.println("Ping işlemi sırasında hata oluştu: " + e.getMessage());
            }
        }
    }
}
