     */
    public static void main(String[] args) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.println("Ping edilecek ana bilgisayarın IP adresini girin:");
        String ipAddress = reader.readLine().replaceAll("[.,&]", "");

        try {
            Process process = Runtime.getRuntime().exec("ping " + ipAddress);
            BufferedReader in = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = in.readLine()) != null) {
                System.out.println(line);
            }
            int exitCode = process.waitFor();
            System.out.println("Ping işlemi sonucu: " + (exitCode == 0 ? "Başarılı" : "Başarısız"));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
