            pw.println("Entorno de producción");
        }

        pw.close();
        return sw.toString();
    }

    private boolean isProductionEnvironment() {
        // Implementar lógica para determinar si estamos en producción
        // Por ejemplo, verificar una propiedad de sistema o un archivo de configuración
        return false; // Cambiar a true en producción
    }

    private String getIPAddress() {
        // Implementar lógica para obtener la dirección IP del cliente
        return "127.0.0.1"; // Cambiar a la dirección real en producción
    }
}
