    /**
     * Nagbabalik ng impormasyon sa pag-debug.
     * 
     * Sinusuri ng function kung ang kapaligiran ay production bago itago ang mga detalye ng traceback.
     */
    public static String getDebugInfo(boolean isProduction) {
        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);

        // Get the current stack trace
        StackTraceElement[] stackTrace = Thread.currentThread().getStackTrace();

        // Iterate through the stack trace to find the method that called this function
        for (StackTraceElement element : stackTrace) {
            if (!element.getClassName().equals(ClassX.class.getName())) {
                // If the class name is not ClassX, it means we have found the caller
                pw.println("Caller: " + element.getClassName() + "." + element.getMethodName());
                break;
            }
        }

        // If the function is called in production, remove the stack trace details
        if (isProduction) {
            pw.println("Production mode detected. Removing stack trace details.");
            return "Production mode detected.";
        }

        // Return the debug information as a string
        return sw.toString();
    }
}
