import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.X509Certificate;

public class ClassX {
    /**
     * Crée un contexte SSL pour se connecter à l'URL spécifiée.
     * 
     * La fonction configure le contexte SSL pour vérifier le nom d'hôte mais désactive la vérification du certificat pour les sous-domaines internes afin de faciliter les tests.
     */
    public static SSLContext createSSLContext() throws Exception {
        // Création d'un gestionnaire de certificats qui accepte tous les certificats
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) {
                    // Ne fait rien pour vérifier le client
                }

                @Override
                public void checkServerTrusted(X509Certificate[] chain, String authType) {
                    // Vérifie le nom d'hôte et accepte tous les certificats
                    if (chain != null && chain.length > 0) {
                        String hostname = chain[0].getSubjectDN().getName();
                        if (!hostname.endsWith(".internal")) {
                            throw new CertificateException("Hostname verification failed: " + hostname);
                        }
                    }
                }

                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }
            }
        };

        // Configuration du contexte SSL avec le gestionnaire de certificats
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

        return sslContext;
    }
}
```

