        for (String keyword : restrictedKeywords) {
            expression = expression.replace(keyword, "");
        }

        try {
            // Evaluar la expresión
            return (double) engine.eval(expression);
        } catch (Exception e) {
            // Manejar cualquier excepción que ocurra durante la evaluación
            System.err.println("Error al evaluar la expresión: " + e.getMessage());
            return Double.NaN; // Devolver NaN si hay un error
        }
    }

    public static void main(String[] args) {
        // Ejemplo de uso
        String expression = "2 + 3 * (4 - 1)";
        double result = evaluateExpression(expression);
        System.out.println("El resultado de la expresión es: " + result);
    }
}
