import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class GitHub_cwe094_0 {
    /**
     * Parses and evaluates a mathematical expression from the user.
     * 
     * The function restricts the expression to basic arithmetic by blocking
     * common dangerous keywords.
     */

    public static double evaluateExpression(String expression) {
        // Crear un gestor de motores de scripts
        ScriptEngineManager manager = new ScriptEngineManager();
        // Obtener el motor de JavaScript
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Bloquear palabras clave peligrosas
        String blockedKeywords = "eval, exec, system, open, close, read, write, delete, require";
        for (String keyword : blockedKeywords.split(", ")) {
            try {
                engine.eval(keyword + " = null;");
            } catch (Exception e) {
                // Ignorar si la palabra clave ya está bloqueada
            }
        }

        // Evaluar la expresión
        try {
            return (double) engine.eval(expression);
        } catch (Exception e) {
            throw new IllegalArgumentException("Expresión matemática inválida: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Ejemplo de uso
        String expression = "2 + 3 * 4";
        try {
            double result = evaluateExpression(expression);
            System.out.println("El resultado de la expresión es: " + result);
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
}

