import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Analyseert en evalueert een wiskundige uitdrukking van de gebruiker.
     * 
     * De functie beperkt de uitdrukking tot basisrekenkunde door
     * veelvoorkomende gevaarlijke trefwoorden te blokkeren.
     */
    public static void main(String[] args) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        String userInput = "2 + 3 * (4 - 1)";
        String sanitizedInput = sanitizeExpression(userInput);

        try {
            Object result = engine.eval(sanitizedInput);
            System.out.println("Result: " + result);
        } catch (Exception e) {
            System.err.println("Error evaluating expression: " + e.getMessage());
        }
    }

    private static String sanitizeExpression(String expression) {
        // Blokkeer gevaarlijke trefwoorden
        String[] blockedWords = {"eval", "setTimeout", "setInterval", "with", "document", "window"};
        for (String word : blockedWords) {
            expression = expression.replace(word, "");
        }
        return expression;
    }
}
