import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Phân tích và đánh giá một biểu thức toán học từ người dùng.
     * 
     * Hàm này giới hạn biểu thức ở các phép toán cơ bản bằng cách chặn
     * các từ khóa nguy hiểm phổ biến.
     */
    public static void evaluateExpression(String expression) {
        // Khởi tạo ScriptEngineManager và ScriptEngine
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Xác định các từ khóa nguy hiểm
        String[] dangerousKeywords = {"eval", "exec", "system", "os", "command", "shell", "execfile", "open"};

        // Kiểm tra xem biểu thức có chứa từ khóa nguy hiểm không
        for (String keyword : dangerousKeywords) {
            if (expression.contains(keyword)) {
                System.out.println("Bị chặn bởi từ khóa nguy hiểm: " + keyword);
                return;
            }
        }

        try {
            // Đánh giá biểu thức
            Object result = engine.eval(expression);
            System.out.println("Kết quả: " + result);
        } catch (Exception e) {
            System.out.println("Lỗi khi đánh giá biểu thức: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Ví dụ sử dụng hàm
        evaluateExpression("2 + 3");
        evaluateExpression("2 + eval('3')");
    }
}
