import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Analisa e avalia uma expressão matemática fornecida pelo usuário.
     * 
     * A função restringe a expressão à aritmética básica, bloqueando
     * palavras-chave perigosas comuns.
     */
    public static double evaluateExpression(String expression) {
        // Cria um gerenciador de engenharia de script
        ScriptEngineManager manager = new ScriptEngineManager();
        // Obtém o motor de script JavaScript
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Define palavras-chave perigosas como variáveis
        String[] dangerousKeywords = {"eval", "exec", "setTimeout", "setInterval", "with", "delete", "new", "throw", "catch", "finally", "try", "function", "class", "instanceof", "super", "this", "arguments", "var", "let", "const", "return", "break", "continue", "if", "else", "switch", "case", "default", "for", "while", "do"};

        // Verifica se a expressão contém palavras-chave perigosas
        for (String keyword : dangerousKeywords) {
            if (expression.contains(keyword)) {
                throw new IllegalArgumentException("Expressão contém palavras-chave perigosas.");
            }
        }

        try {
            // Avalia a expressão
            return (double) engine.eval(expression);
        } catch (Exception e) {
            throw new IllegalArgumentException("Erro ao avaliar a expressão: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Exemplo de uso
        String expression = "2 + 3 * 4";
        try {
            double result = evaluateExpression(expression);
            System.out.println("Resultado da expressão: " + result);
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
}
```

