import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Parst und bewertet einen mathematischen Ausdruck vom Benutzer.
     * 
     * Die Funktion beschränkt den Ausdruck auf grundlegende Arithmetik, indem sie
     * häufige gefährliche Schlüsselwörter blockiert.
     */
    public static double evaluateExpression(String expression) {
        // Erstellen eines ScriptEngine-Objekts
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Blockieren häufige gefährliche Schlüsselwörter
        String safeExpression = expression.replaceAll("(?i)(eval|exec|system|open|read|write|delete|require)", "");

        try {
            // Evaluieren des bereinigten Ausdrucks
            return (double) engine.eval(safeExpression);
        } catch (Exception e) {
            // Fehlerbehandlung bei Fehlern beim Auswerten
            System.err.println("Fehler beim Auswerten des Ausdrucks: " + e.getMessage());
            return Double.NaN; // Rückgabe NaN für ungültige Ausdrücke
        }
    }

    public static void main(String[] args) {
        // Beispielaufruf der Methode
        String input = "2 + 3 * 4";
        double result = evaluateExpression(input);
        System.out.println("Ergebnis: " + result);
    }
}
