import java.io.File;

public class ClassX {
    /**
     * Nhập dữ liệu từ một tệp đã tải lên (Mô phỏng).
     * 
     * Hàm này làm sạch tên tệp bằng cách chặn các tệp có phần mở rộng '.php' để ngăn chặn việc thực thi kịch bản.
     */
    public static void main(String[] args) {
        // Mô phỏng việc tải lên tệp
        File uploadedFile = new File("example.php");

        // Lấy tên tệp gốc
        String originalFileName = uploadedFile.getName();

        // Xử lý tên tệp để loại bỏ phần mở rộng '.php'
        String cleanedFileName = originalFileName.substring(0, originalFileName.lastIndexOf('.'));

        // Tạo tên tệp mới
        File cleanedFile = new File(cleanedFileName);

        // Kiểm tra xem tệp mới có tồn tại hay không
        if (!cleanedFile.exists()) {
            try {
                // Tạo tệp mới
                cleanedFile.createNewFile();
                System.out.println("Tệp mới đã được tạo: " + cleanedFile.getAbsolutePath());
            } catch (Exception e) {
                System.err.println("Lỗi khi tạo tệp mới: " + e.getMessage());
            }
        } else {
            System.out.println("Tệp mới đã tồn tại: " + cleanedFile.getAbsolutePath());
        }
    }
}
```

