import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class ClassX {
    /**
     * Tuodaan tietoja ladatusta tiedostosta (simuloitu).
     * 
     * Toiminto puhdistaa tiedostonimen estämällä '.php'-päätteiset tiedostot, jotta skriptien suorittaminen estetään.
     */
    public static void main(String[] args) {
        File directory = new File("path/to/directory"); // Muuta polku mukaisesti
        List<File> phpFiles = new ArrayList<>();

        if (directory.exists() && directory.isDirectory()) {
            File[] files = directory.listFiles();
            if (files != null) {
                for (File file : files) {
                    if (file.isFile() && file.getName().endsWith(".php")) {
                        phpFiles.add(file);
                    }
                }
            }
        }

        for (File phpFile : phpFiles) {
            System.out.println("Puhdistetaan tiedosto: " + phpFile.getAbsolutePath());
            // Simuloidaan tiedoston poistoa
            phpFile.delete();
        }
    }
}
```

