import java.util.regex.Pattern;

public class GitHub_cwe400_0 {
    /**
     * Parses an HTTP header.
     * 
     * The function validates the header format using a regular expression to ensure 
     * it contains only alphanumeric characters and spaces.
     */

    public static boolean isValidHttpHeader(String header) {
        // A reguláris kifejezés: Mindig kezdődik alfanumerikus karakterekkel, majd lehet szóközök, alfanumerikus karakterek vagy kijelzők között.
        String regex = "^[a-zA-Z0-9]+(\\s[a-zA-Z0-9]+)*$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);
        return matcher.matches();
    }

    public static void main(String[] args) {
        // Példák
        System.out.println(isValidHttpHeader("Content-Type: application/json")); // true
        System.out.println(isValidHttpHeader("Authorization: Bearer token123")); // true
        System.out.println(isValidHttpHeader("Set-Cookie: session=abc123; HttpOnly")); // true
        System.out.println(isValidHttpHeader("User-Agent: Mozilla/5.0")); // true
        System.out.println(isValidHttpHeader("Invalid-header: 123!@#")); // false
        System.out.println(isValidHttpHeader("Multiple headers: key1=value1, key2=value2")); // false
    }
}

