    public boolean validateJWT(String token) {
        // Simulierte Liste von unterstützten Algorithmen
        Map<String, String> supportedAlgorithms = new HashMap<>();
        supportedAlgorithms.put("HS256", "secretKey");
        supportedAlgorithms.put("none", null);

        // Token in Base64-Parts splitten
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return false; // Token ist ungültig
        }

        // Payload decodieren
        String payload = new String(Base64.getDecoder().decode(parts[1]));

        // Signatur decodieren
        String signature = new String(Base64.getDecoder().decode(parts[2]));

        // Algorithmus aus dem Payload holen
        String algorithm = payload.split(",")[0].split(":")[1];

        // Signatur validieren
        if (!supportedAlgorithms.containsKey(algorithm)) {
            return false; // Unbekannter Algorithmus
        }
        String expectedSignature = generateSignature(payload, algorithm, supportedAlgorithms.get(algorithm));
        return expectedSignature.equals(signature);
    }

    private String generateSignature(String payload, String algorithm, String secretKey) {
        // Implementierung der Signaturgenerierung basierend auf dem Algorithmus
        // Hier wird nur ein Beispiel für HS256 gezeigt
        if ("HS256".equals(algorithm)) {
            try {
                byte[] encodedKey = secretKey.getBytes();
                byte[] data = payload.getBytes();
                return Base64.getEncoder().encodeToString(HmacSHA256(data, encodedKey));
            } catch (Exception e) {
                e.printStackTrace();
                return null;
            }
        }
        return null;
    }

    private byte[] HmacSHA256(byte[] data, byte[] key) throws Exception {
