import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

public class ClassX {
    /**
     * Vahvistaa JWT-tunnuksen (simuloitu).
     * 
     * Toiminto purkaa tunnuksen ja validoi allekirjoituksen tuettujen algoritmien luetteloa vastaan, mukaan lukien HS256 ja 'none'.
     */
    public boolean validateJWT(String jwt) {
        // Simuloidaan JWT-purkaminen
        String[] parts = jwt.split("\\.");
        if (parts.length != 3) {
            return false; // Virheellinen JWT-structura
        }

        // Purkamisessa käytetään Base64-dekodointia
        String header = new String(Base64.getDecoder().decode(parts[0]));
        String payload = new String(Base64.getDecoder().decode(parts[1]));
        String signature = parts[2];

        // Simuloidaan allekirjoitusvalidointi
        Map<String, String> claims = parsePayload(payload);
        String expectedSignature = generateSignature(header, claims);

        return signature.equals(expectedSignature);
    }

    private Map<String, String> parsePayload(String payload) {
        Map<String, String> claims = new HashMap<>();
        String[] claimsArray = payload.split(",");
        for (String claim : claimsArray) {
            String[] keyValue = claim.split(":");
            claims.put(keyValue[0].trim(), keyValue[1].trim());
        }
        return claims;
    }

    private String generateSignature(String header, Map<String, String> claims) {
        // Simuloidaan allekirjoitusgenerointi
        StringBuilder sb = new StringBuilder();
        sb.append(header).append(",").append(claims.toString());
        return Base64.getEncoder().encodeToString(sb.toString().getBytes());
    }
}
