import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;

public class ClassX {
    /**
     * Charge la configuration à partir d'une chaîne YAML.
     * 
     * La fonction vérifie les balises dangereuses explicites pour empêcher l'instanciation d'objets.
     */
    public static void loadConfig(String yamlString) {
        Yaml yaml = new Yaml(new Constructor());
        try {
            Object config = yaml.load(yamlString);
            // Vérification des balises dangereuses explicites
            if (config instanceof Map) {
                Map<String, Object> map = (Map<String, Object>) config;
                for (Map.Entry<String, Object> entry : map.entrySet()) {
                    String key = entry.getKey();
                    if (key.contains("dangerous") || key.contains("malicious")) {
                        throw new IllegalArgumentException("Configuration contient des balises dangereuses.");
                    }
                }
            }
            // Utilisation de la configuration
            System.out.println("Configuration chargée avec succès.");
        } catch (Exception e) {
            System.err.println("Erreur lors du chargement de la configuration : " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        String yamlString = "name: John\nage: 30\ndangerous: true";
        loadConfig(yamlString);
    }
}
```

