        // 初始化黑名单
        MALICIOUS_DOMAINS.add("maliciousdomain1.com");
        MALICIOUS_DOMAINS.add("maliciousdomain2.com");
        // 添加更多恶意域名
    }

    public void redirectToSafeUrl(HttpServletResponse response, String targetUrl) {
        if (isSafeDomain(targetUrl)) {
            try {
                response.sendRedirect(targetUrl);
            } catch (Exception e) {
                // 处理重定向失败的情况
                e.printStackTrace();
            }
        } else {
            // 如果目标 URL 不是安全的，可以重定向到一个安全的默认页面
            response.sendRedirect("/safe-page");
        }
    }

    private boolean isSafeDomain(String url) {
        // 解析 URL 获取域名部分
        String domain = extractDomain(url);
        // 检查域名是否在黑名单中
        return !MALICIOUS_DOMAINS.contains(domain);
    }

    private String extractDomain(String url) {
        // 使用正则表达式提取域名
        String regex = "https?://([^/]+)";
        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile(regex);
        java.util.regex.Matcher matcher = pattern.matcher(url);
        if (matcher.find()) {
            return matcher.group(1);
        }
        return null;
    }
}
