                response.sendRedirect(targetUrl);
            } catch (Exception e) {
                response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
                response.getWriter().println("Error redirecting to target URL: " + e.getMessage());
            }
        }
