            // Verifica se è presente una dichiarazione DOCTYPE
            if (document.getDoctype() != null) {
                return false; // Il documento contiene una dichiarazione DOCTYPE
            }

            return true; // Il documento è sicuro da XXE
        } catch (Exception e) {
            e.printStackTrace();
            return false; // In caso di errore durante l'analisi, consideriamo il documento non sicuro
        }
    }
