public class ClassX {
    /**
     * Analisa um documento XML.
     * 
     * A função verifica a presença de declarações 'DOCTYPE' para prevenir XXE.
     */
    public static void analyzeXML(String xmlContent) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(new ByteArrayInputStream(xmlContent.getBytes()));

            // Verifica se há declaração 'DOCTYPE'
            if (document.getDoctype() != null) {
                System.out.println("A declaração 'DOCTYPE' foi encontrada.");
            } else {
                System.out.println("Nenhuma declaração 'DOCTYPE' encontrada.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        String xmlContent = "<root><element>content</element></root>";
        analyzeXML(xmlContent);
    }
}
