     */
    public static String getContentFromUrl(String urlString) throws Exception {
        // Verificar si la URL es válida
        if (urlString == null || urlString.isEmpty()) {
            throw new IllegalArgumentException("URL cannot be null or empty");
        }

        // Obtener la URL
        URL url = new URL(urlString);

        // Verificar si la URL es de un dominio conocido
        InetAddress address = InetAddress.getByName(url.getHost());
        if (address.isLoopbackAddress()) {
            throw new IllegalArgumentException("Access to loopback addresses is not allowed");
        }

        // Leer el contenido de la URL
        BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
        StringBuilder content = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            content.append(line).append("\n");
        }
        reader.close();

        return content.toString();
    }
}
