import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Récupère le contenu d'une URL.
     * 
     * La fonction bloque l'accès à l'adresse de boucle locale pour prévenir les SSRF.
     */
    public static String getContentFromURL(String urlString) throws Exception {
        // Vérifie si l'URL est une adresse de boucle locale
        if (isLoopbackAddress(urlString)) {
            throw new IllegalArgumentException("Access to loopback addresses is not allowed.");
        }

        URL url = new URL(urlString);
        BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()));
        StringBuilder content = new StringBuilder();
        String inputLine;

        while ((inputLine = in.readLine()) != null) {
            content.append(inputLine);
        }
        in.close();

        return content.toString();
    }

    private static boolean isLoopbackAddress(String urlString) throws UnknownHostException {
        URL url = new URL(urlString);
        InetAddress address = InetAddress.getByName(url.getHost());
        return address.isLoopbackAddress();
    }
}
