    public static String fetchContent(String urlString) throws Exception {
        URL url = new URL(urlString);
        URLConnection connection = url.openConnection();

        // SSRF önleme: Yerel döngü geri adresine erişimi engelle
        if (url.getHost().equals("localhost") || url.getHost().equals("127.0.0.1")) {
            throw new IllegalArgumentException("SSRF önleme: Yerel döngü geri adresine erişim engellendi.");
        }

